87				out[occurrenceKey{id: lm.ID, num: 1}] = lm.LegacyCount
88				continue
89			}
90			for _, oj := range lm.Occurrences {
91				out[occurrenceKey{id: lm.ID, num: oj.Number}] = oj.LegacyCount
92			}
